(()=>{
 const base=new URL('.',document.currentScript?.src||new URL('launch.js',document.baseURI).href).pathname;
 // Retire only this game's offline worker; keep saved progress and music.
 navigator.serviceWorker?.getRegistration(base).then(reg=>{if(reg&&new URL(reg.active?.scriptURL||reg.waiting?.scriptURL||'',location.href).pathname===base+'sw.js')return reg.unregister();}).catch(()=>{});
 const panel=document.getElementById('launch-status'),text=document.getElementById('launch-message'),root=document.getElementById('root');let started=false;
 function show(message){if(panel){panel.hidden=false;text.textContent=message;}}
 const check=()=>{if(root?.querySelector('.game-frame')){started=true;if(panel)panel.hidden=true;}else if(started)show('The game stopped. Refresh the saved game below to try again.');};
 const observer=new MutationObserver(check);if(root)observer.observe(root,{childList:true});check();
 const timer=setTimeout(()=>{if(!started)show('The game has not opened yet. Check your connection or refresh the saved game.');},8000);
 async function repair(){const button=document.getElementById('launch-repair');if(button)button.disabled=true;show('Checking the latest game…');try{if(navigator.onLine===false)throw new Error('offline');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);let response;try{response=await fetch(base+'icons/icon.svg?check='+Date.now(),{cache:'no-store',signal:controller.signal});}finally{clearTimeout(timeout);}if(!response.ok||!(await response.text()).includes('<svg'))throw new Error('Connect to the internet, then try again.');try{const registration=await navigator.serviceWorker?.getRegistration(base);if(registration&&new URL(registration.active?.scriptURL||registration.waiting?.scriptURL||base+'sw.js',location.href).pathname===base+'sw.js')await registration.unregister();}catch{}try{for(const key of await caches.keys())if(key.startsWith('egg-tissue-pwa-'+(base==='/'?'':encodeURIComponent(base)+'-')))await caches.delete(key);}catch{}location.replace(base+'?recovered='+Date.now()+'#/home');}catch{show('Connect to the internet and tap Refresh saved game again. Your progress is still saved.');if(button)button.disabled=false;}}
 document.getElementById('launch-reload')?.addEventListener('click',()=>location.reload());document.getElementById('launch-repair')?.addEventListener('click',repair);window.addEventListener('error',()=>{if(!root?.querySelector('.game-frame'))show('The game could not open. Refresh the saved game below.');});window.addEventListener('pagehide',()=>{clearTimeout(timer);observer.disconnect();});window.eggRecovery={repair};
})();
